在JavaScript中属性名称作为参数的API是相当普遍的，但是到目前为止还没有表达在那些API中出现的类型关系。 输入索引类型查询或keyof，索引类型查询keyof T产生的类型是T的属性名称。keyof T的类型被认为是string的子类型。 示例 interface Person { name: string; age: number; location: string;
} type K1 = keyof Person; // "name" | "age" | "location"
type K2 = keyof Person[]; // "length" | "push" | "pop" | "concat" | ...
type K3 = keyof { [x: string]: Person }; // string 与之相对应的是_索引访问类型_，也称为_查找类型_。在语法上，它们看起来像元素访问，但是写成类型： 示例 type P1 = Person["name"]; // string
type P2 = Person["name" | "age"]; // string | number
type P3 = string["charAt"]; // (pos: number) => string
type P4 = string[]["push"]; // (...items: string[]) => number
type P5 = string[][0]; // string 你可以将这种模式和类型系统的其它部分一起使用，以获取类型安全的查找。 function getProperty<T, K extends keyof T>(obj: T, key: K) { return obj[key]; // 推断类型是T[K]
} function setProperty<T, K extends keyof T>(obj: T, key: K, value: T[K]) { obj[key] = value;
} let x = { foo: 10, bar: "hello!" }; let foo = getProperty(x, "foo"); // number
let bar = getProperty(x, "bar"); // string let oops = getProperty(x, "wargarbl"); // 错误！"wargarbl"不存在"foo" | "bar"中 setProperty(x, "foo", "string"); // 错误！, 类型是number而非string

1027.body:
一个常见的任务是使用现有类型并使其每个属性完全可选。假设我们有一个Person： interface Person { name: string; age: number; location: string;
} Person的可选属性类型将是这样： interface PartialPerson { name?: string; age?: number; location?: string;
} 使用映射类型，PartialPerson可以写成是Person类型的广义变换： type Partial<T> = { [P in keyof T]?: T[P];
}; type PartialPerson = Partial<Person>; 映射类型是通过使用字面量类型的集合而生成的，并为新对象类型计算一组属性。它们就像 Python中的列表推导式 ，但不是在列表中产生新的元素，而是在类型中产生新的属性。 除Partial外，映射类型可以表示许多有用的类型转换： // 保持类型相同，但每个属性是只读的。
type Readonly<T> = { readonly [P in keyof T]: T[P];
}; // 相同的属性名称，但使值是一个Promise，而不是一个具体的值
type Deferred<T> = { [P in keyof T]: Promise<T[P]>;
}; // 为T的属性添加代理
type Proxify<T> = { [P in keyof T]: { get(): T[P]; set(v: T[P]): void }
};

1028.body:
Partial和Readonly，如前所述，是非常有用的结构。你可以使用它们来描述像一些常见的JS程序： function assign<T>(obj: T, props: Partial<T>): void;
function freeze<T>(obj: T): Readonly<T>; 因此，它们现在默认包含在标准库中。 我们还包括两个其他实用程序类型：Record和Pick。 // 从T中选取一组属性K
declare function pick<T, K extends keyof T>(obj: T, ...keys: K[]): Pick<T, K>; const nameAndAgeOnly = pick(person, "name", "age"); // { name: string, age: number } // 对于类型T的每个属性K，将其转换为U
function mapObject<K extends string | number, T, U>(obj: Record<K, T>, f: (x: T) => U): Record<K, U> const names = { foo: "hello", bar: "world", baz: "bye" };
const lengths = mapObject(names, s => s.length); // { foo: number, bar: number, baz: number }

