使用联合的一种常用技术是使用字面量类型的单个字段，您可以使用该字段来缩小 TypeScript 可能的当前类型。例如，我们将创建一个包含三种类型的联合，这些类型具有一个共享字段。 type NetworkLoadingState = { state: "loading";
}; type NetworkFailedState = { state: "failed"; code: number;
}; type NetworkSuccessState = { state: "success"; response: { title: string; duration: number; summary: string; };
}; // 创建一个只代表上述类型之一的类型，但你还不确定它是哪个。
type NetworkState = | NetworkLoadingState | NetworkFailedState | NetworkSuccessState; 上述类型都以一个名为state的字段，然后它们也有自己的字段。 NetworkLoadingState NetworkFailedState NetworkSuccessState state state state code response 鉴于state字段在NetworkState的每个类型中都是通用的--你的代码无需存在检查即可安全访问。 有了state这个字面类型，你可以将state的值与相应的字符串进行比较，TypeScript就会知道当前使用的是哪个类型。 NetworkLoadingState NetworkFailedState NetworkSuccessState "loading" "failed" "success" 在这个例子中，你可以使用switch语句来缩小在运行时代表哪种类型： // @errors: 2339
type NetworkLoadingState = { state: "loading";
}; type NetworkFailedState = { state: "failed"; code: number;
}; type NetworkSuccessState = { state: "success"; response: { title: string; duration: number; summary: string; };
};
// ---cut---
type NetworkState = | NetworkLoadingState | NetworkFailedState | NetworkSuccessState; function logger(state: NetworkState): string { // 现在，TypeScript不知道state是三种可能类型中的哪一种。 // 试图访问一个不是所有类型都共享的属性将引发一个错误 state.code; // 通过选择state，TypeScript可以在代码流分析中缩小联合的范围 switch (state.state) { case "loading": return "Downloading..."; case "failed": // 这里的类型一定是NetworkFailedState，所以访问`code`字段是安全的。 return `Error ${state.code} downloading`; case "success": return `Downloaded ${state.response.title} - ${state.response.summary}`; }
}

