} class MyComponent { // 在元素实例类型上指定属性 props: { foo?: string; }
} // `MyComponent`的元素属性类型为`{foo?: string}`
<MyComponent foo="bar" /> 元素属性类型用于的JSX里进行属性的类型检查。 支持可选属性和必须属性。 declare namespace JSX { interface IntrinsicElements { foo: { requiredProp: string; optionalProp?: number } }
} <foo requiredProp="bar" />; // 正确
