475.body:
不要 把模糊的重载放在具体的重载前面： /* 错误 */
declare function fn(x: any): any;
declare function fn(x: HTMLElement): number;
declare function fn(x: HTMLDivElement): string; var myElem: HTMLDivElement;
var x = fn(myElem); // x: any, wat? 应该 将重载排序，把具体的排在模糊的之前： /* 正确 */
declare function fn(x: HTMLDivElement): string;
declare function fn(x: HTMLElement): number;
declare function fn(x: any): any; var myElem: HTMLDivElement;
var x = fn(myElem); // x: string, :) 原因 ：当解析函数调用的时候，TypeScript 会选择 匹配到的第一个重载 。 当位于前面的重载比后面的“更模糊”，那么后面的会被隐藏且不会被选用。

