字符串索引签名可用于为类似于字典的对象添加类型，它表示允许使用任意的键来访问对象： const movieWatchCount: { [key: string]: number } = {}; function watchMovie(title: string) { movieWatchCount[title] = (movieWatchCount[title] ?? 0) + 1;
} 当然了，对于不在字典中的电影名而言 movieWatchCount[title] 的值为 undefined。（TypeScript 4.1 增加了 --noUncheckedIndexedAccess 选项，在访问索引签名时会增加 undefined 值。） 即便一定会有 movieWatchCount 中不存在的属性，但在之前的版本中，由于 undefined 值的存在，TypeScript 会将可选对象属性视为不可以赋值给兼容的索引签名。 type WesAndersonWatchCount = { 'Fantastic Mr. Fox'?: number; 'The Royal Tenenbaums'?: number; 'Moonrise Kingdom'?: number; 'The Grand Budapest Hotel'?: number;
}; declare const wesAndersonWatchCount: WesAndersonWatchCount;
const movieWatchCount: { [key: string]: number } = wesAndersonWatchCount;
// ~~~~~~~~~~~~~~~ 错误！
// 类型 'WesAndersonWatchCount' 不允许赋值给类型 '{ [key: string]: number; }'。
// 属性 '"Fantastic Mr. Fox"' 与索引签名不兼容。
// 类型 'number | undefined' 不允许赋值给类型 'number'。
// 类型 'undefined' 不允许赋值给类型 'number'。 (2322) TypeScript 4.2 允许这样赋值。 但是不允许使用带有 undefined 类型的非可选属性进行赋值，也不允许将 undefined 值直接赋值给某个属性： type BatmanWatchCount = { 'Batman Begins': number | undefined; 'The Dark Knight': number | undefined; 'The Dark Knight Rises': number | undefined;
}; declare const batmanWatchCount: BatmanWatchCount; // 在 TypeScript 4.2 中仍是错误。
const movieWatchCount: { [key: string]: number } = batmanWatchCount; // 在 TypeScript 4.2 中仍是错误。
// 索引签名不允许显式地赋值 `undefined`。
movieWatchCount["It's the Great Pumpkin, Charlie Brown"] = undefined; 这条新规则不适用于数字索引签名，因为它们被当成是类数组的并且是稠密的： declare let sortOfArrayish: { [key: number]: string };
declare let numberKeys: { 42?: string }; sortOfArrayish = numberKeys; 更多详情，请参考 PR 。

783.body:
使用字符串字面量类型能够表示仅接受特定字符串参数的函数和 API。 function setVerticalAlignment(location: 'top' | 'middle' | 'bottom') { // ...
} setVerticalAlignment('middel');
// ^^^^^^^^
// Argument of type '"middel"' is not assignable to parameter of type '"top" | "middle" | "bottom"'. 使用字符串字面量类型的好处是它能够对字符串进行拼写检查。 此外，字符串字面量还能用于映射类型中的属性名。 从这个意义上来讲，它们可被当作构件使用。 type Options = { [K in | 'noImplicitAny' | 'strictNullChecks' | 'strictFunctionTypes']?: boolean;
};
// same as
// type Options = {
// noImplicitAny?: boolean,
// strictNullChecks?: boolean,
// strictFunctionTypes?: boolean
// }; 还有一处字符串字面量类型可被当作构件使用，那就是在构造其它字符串字面量类型时。 这也是 TypeScript 4.1 支持模版字面量类型的原因。 它的语法与 JavaScript 中的模版字面量 的语法是一致的，但是是用在表示类型的位置上。 当将其与具体类型结合使用时，它会将字符串拼接并产生一个新的字符串字面量类型。 type World = 'world'; type Greeting = `hello ${World}`;
// ^^^^^^^^^
// "hello world" 如果在替换的位置上使用了联合类型会怎么样呢？ 它将生成由各个联合类型成员所表示的字符串字面量类型的联合。 type Color = 'red' | 'blue';
type Quantity = 'one' | 'two'; type SeussFish = `${Quantity | Color} fish`;
// ^^^^^^^^^
// "one fish" | "two fish" | "red fish" | "blue fish" 除此之外，我们也可以在其它场景中应用它。 例如，有些 UI 组件库提供了指定垂直和水平对齐的 API，通常会使用类似于"bottom-right"的字符串来同时指定。 在垂直对齐的选项"top"，"middle"和"bottom"，以及水平对齐的选项"left"，"center"和"right"之间，共有 9 种可能的字符串，前者选项之一与后者选项之一之间使用短横线连接。 type VerticalAlignment = 'top' | 'middle' | 'bottom';
type HorizontalAlignment = 'left' | 'center' | 'right'; // Takes
// | "top-left" | "top-center" | "top-right"
// | "middle-left" | "middle-center" | "middle-right"
// | "bottom-left" | "bottom-center" | "bottom-right" declare function setAlignment( value: `${VerticalAlignment}-${HorizontalAlignment}`
): void; setAlignment('top-left'); // works!
setAlignment('top-middel'); // error!
setAlignment('top-pot'); // error! but good doughnuts if you're ever in Seattle 这样的例子还有很多，但它仍只是小例子而已，因为我们可以直接写出所有可能的值。 实际上，对于 9 个字符串来讲还算可以；但是如果需要大量的字符串，你就得考虑如何去自动生成（或者简单地使用string）。 有些值实际上是来自于动态创建的字符串字面量。 例如，假设 makeWatchedObject API 接收一个对象，并生成一个几乎等同的对象，但是带有一个新的on方法来检测属性的变化。 let person = makeWatchedObject({ firstName: 'Homer', age: 42, location: 'Springfield',
}); person.on('firstNameChanged', () => { console.log(`firstName was changed!`);
}); 注意，on监听的是"firstNameChanged"事件，而非仅仅是"firstName"。 那么我们如何定义类型？ type PropEventSource<T> = { on(eventName: `${string & keyof T}Changed`, callback: () => void): void;
}; /// Create a "watched object" with an 'on' method
/// so that you can watch for changes to properties.
declare function makeWatchedObject<T>(obj: T): T & PropEventSource<T>; 这样做的话，如果传入了错误的属性会产生一个错误！ type PropEventSource<T> = { on(eventName: `${string & keyof T}Changed`, callback: () => void): void;
};
declare function makeWatchedObject<T>(obj: T): T & PropEventSource<T>;
let person = makeWatchedObject({ firstName: 'Homer', age: 42, location: 'Springfield',
}); // error!
person.on('firstName', () => {}); // error!
person.on('frstNameChanged', () => {}); 我们还可以在模版字面量上做一些其它的事情：可以从替换的位置来 推断 类型。 我们将上面的例子改写成泛型，由eventName字符串来推断关联的属性名。 type PropEventSource<T> = { on<K extends string & keyof T>( eventName: `${K}Changed`, callback: (newValue: T[K]) => void ): void;
}; declare function makeWatchedObject<T>(obj: T): T & PropEventSource<T>; let person = makeWatchedObject({ firstName: 'Homer', age: 42, location: 'Springfield',
}); // works! 'newName' is typed as 'string'
person.on('firstNameChanged', (newName) => { // 'newName' has the type of 'firstName' console.log(`new name is ${newName.toUpperCase()}`);
}); // works! 'newAge' is typed as 'number'
person.on('ageChanged', (newAge) => { if (newAge < 0) { console.log('warning! negative age'); }
}); 这里我们将on定义为泛型方法。 当用户使用"firstNameChanged'来调用该方法，TypeScript 会尝试去推断出K所表示的类型。 为此，它尝试将K与"Changed"之前的内容进行匹配并推断出"firstName"。 一旦 TypeScript 得到了结果，on方法就能够从原对象上获取firstName的类型，此例中是string。 类似地，当使用"ageChanged"调用时，它会找到属性age的类型为number。 类型推断可以用不同的方式组合，常见的是解构字符串，再使用其它方式重新构造它们。 实际上，为了便于修改字符串字面量类型，我们引入了一些新的工具类型来修改字符大小写。 type EnthusiasticGreeting<T extends string> = `${Uppercase<T>}`; type HELLO = EnthusiasticGreeting<'hello'>;
// ^^^^^
// "HELLO" 新的类型别名为Uppercase，Lowercase，Capitalize和Uncapitalize。 前两个会转换字符串中的所有字符，而后面两个只转换字符串的首字母。 更多详情， 查看原 PR 以及 正在进行中的切换类型别名助手的 PR .

