让我们先回顾一下，映射类型可以使用任意的键来创建新的对象类型。 type Options = { [K in | 'noImplicitAny' | 'strictNullChecks' | 'strictFunctionTypes']?: boolean;
};
// same as
// type Options = {
// noImplicitAny?: boolean,
// strictNullChecks?: boolean,
// strictFunctionTypes?: boolean
// }; 或者，基于任意的对象类型来创建新的对象类型。 /// 'Partial<T>' 等同于 'T'，只是把每个属性标记为可选的。
type Partial<T> = { [K in keyof T]?: T[K];
}; 到目前为止，映射类型只能使用提供给它的键来创建新的对象类型；然而，很多时候我们想要创建新的键，或者过滤掉某些键。 这就是 TypeScript 4.1 允许更改映射类型中的键的原因。它使用了新的as语句。 type MappedTypeWithNewKeys<T> = { [K in keyof T as NewKeyType]: T[K]; // ^^^^^^^^^^^^^ // 这里是新的语法！
}; 通过as语句，你可以利用例如模版字面量类型，并基于原属性名来轻松地创建新属性名。 type Getters<T> = { [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
}; interface Person { name: string; age: number; location: string;
} type LazyPerson = Getters<Person>;
// type LazyPerson = {
// getName: () => string;
// getAge: () => number;
// getLocation: () => string;
// } 此外，你可以巧用never类型来过滤掉某些键。 也就是说，在某些情况下你不必使用Omit工具类型。 // 删除 'kind' 属性
type RemoveKindField<T> = { [K in keyof T as Exclude<K, 'kind'>]: T[K];
}; interface Circle { kind: 'circle'; radius: number;
} type KindlessCircle = RemoveKindField<Circle>; type RemoveKindField<T> = { [K in keyof T as Exclude<K, 'kind'>]: T[K];
}; interface Circle { kind: 'circle'; radius: number;
} type KindlessCircle = RemoveKindField<Circle>;
// type KindlessCircle = {
// radius: number;
// } 更多详情，请参考 PR 。

