}; type Label = { name: string;
}; const thing: Point | Label = { x: 0, y: 0, name: true // uh-oh!
}; 以前，一个无区别的联合在它的成员上不会进行_任何_多余属性的检查，结果，类型错误的 name 属性溜了进来。 在 TypeScript 3.5 中，类型检查器至少会验证所有提供的属性属于_某个_联合类型的成员，且类型恰当，这意味着，上面的例子会正确的进行错误提示。 注意，只要属性类型有效，仍允许部分重叠。 const pl: Point | Label = { x: 0, y: 0, name: "origin" // okay
};

