在 TypeScript 3.4 中，我们改进了对返回函数的泛型函数的推断： function compose<T, U, V>(f: (x: T) => U, g: (y: U) => V): (x: T) => V { return x => g(f(x))
} 将其他泛型函数作为参数，如下所示： function arrayify<T>(x: T): T[] { return [x];
} type Box<U> = { value: U }
function boxify<U>(y: U): Box<U> { return { value: y };
} let newFn = compose(arrayify, boxify); TypeScript 3.4 的推断允许 newFn 是泛型的。它的新类型是 <T>（x：T）=> Box <T []>。而不是旧版本推断的，相对无用的类型，如 （x：{}）=> Box <{} []>。 TypeScript 3.5 在处理构造函数的时候推广了这种行为。 class Box<T> { kind: "box"; value: T; constructor(value: T) { this.value = value; }
} class Bag<U> { kind: "bag"; value: U; constructor(value: U) { this.value = value; }
} function composeCtor<T, U, V>(F: new (x: T) => U, G: new (y: U) => V): (x: T) => V { return x => new G(new F(x))
} let f = composeCtor(Box, Bag); // 拥有类型 '<T>(x: T) => Bag<Box<T>>'
let a = f(1024); // 拥有类型 'Bag<Box<number>>' 除了上面的组合模式之外，这种对泛型构造函数的新推断意味着在某些 UI 库（如 React ）中对类组件进行操作的函数可以更正确地对泛型类组件进行操作。 type ComponentClass<P> = new (props: P) => Component<P>;
declare class Component<P> { props: P; constructor(props: P);
} declare function myHoc<P>(C: ComponentClass<P>): ComponentClass<P>; type NestedProps<T> = { foo: number, stuff: T }; declare class GenericComponent<T> extends Component<NestedProps<T>> { } // 类型为 'new <T>(props: NestedProps<T>) => Component<NestedProps<T>>'
const GenericComponent2 = myHoc(GenericComponent); 想学习更多， 在 GitHub 上查看原始的 pull requet 。

